BEGIN; SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; DO $$ DECLARE original public.users%ROWTYPE; affected bigint; BEGIN
IF current_database()<>'simplestchat' OR current_user<>'postgres'
 OR (pg_control_system()).system_identifier::text<>'7498765432109876543' THEN
 RAISE EXCEPTION 'Destination database identity mismatch'; END IF;
SELECT * INTO STRICT original FROM public.users WHERE email='owner@old.example.test' FOR UPDATE;
IF EXISTS(SELECT FROM public.users WHERE email='owner@new.example.test')
 OR NOT EXISTS(SELECT FROM public.rooms WHERE id='lobby' AND owner_id=original.id) THEN
 RAISE EXCEPTION 'Managed owner precondition failed'; END IF;
UPDATE public.users SET email='owner@new.example.test' WHERE id=original.id AND email='owner@old.example.test';
GET DIAGNOSTICS affected=ROW_COUNT;
IF affected<>1 OR (SELECT to_jsonb(u)-'email' FROM public.users u WHERE id=original.id)
 IS DISTINCT FROM (to_jsonb(original)-'email') THEN
 RAISE EXCEPTION 'Managed owner preservation failed'; END IF;
END $$;
COMMIT;

